			title = "Significance",
			text = [=[Nials is the voice of a kingdom that refuses to die. When the dwarves of the {link:thandol-span}Thandol Span{/link} begged her for soldiers, she refused them, grieving. Honor, she said, held her army in the highlands until the king's banner rose again over {link:stromgarde-keep}Stromgarde{/link}.]=],
		},
		{
			title = "Deeds",
			text = [=[• She sends fighters against the {link:syndicate}Syndicate{/link} at {link:northfold-manor}Northfold Manor{/link}, to keep open the supply roads from {link:southshore}Southshore{/link}.
• She pays for the badges of fallen militiamen taken back from the Syndicate, so that the families of the dead may know their fate.
• She holds the bounties on the Syndicate warlock {link:marez-cowl}Marez Cowl{/link}, on {link:lord-falconcrest}Lord Falconcrest{/link} and on his bodyguard Otto.]=],
		},
		{
			title = "Unrecorded",
			text = [=[The records of {link:refuge-pointe}Refuge Pointe{/link} give only her rank and her deeds. Nothing is written of her life before the fall of the city.]=],
		},
	},
	chapters = {
		{
			key = "the-plea-from-the-span",
			title = "The Plea from the Span",
			hint = [=[Bring the plea of the dwarves of the Wetlands to Refuge Pointe.]=],
			unlock = {
				{ type = "quest", id = 634 },
			},
			text = [=[The dwarves of {link:dun-modr}Dun Modr{/link} had lost their town and half their bridge, and they sent to {link:refuge-pointe}Refuge Pointe{/link} for help. Nials heard the news of the {link:thandol-span}Thandol Span{/link} with a heavy heart. Yet she had nothing to give. {link:stromgarde-keep}Stromgarde{/link} had fallen, and every sword she had was needed to take it back. She sent word that the dwarves must stand alone.]=],
		},
		{
			key = "the-badges-of-the-fallen",
			title = "The Badges of the Fallen",
			hint = [=[Recover what the Syndicate takes from the dead of Stromgarde.]=],
			unlock = {
				{ type = "quest", id = 682 },
			},
			text = [=[The {link:syndicate}Syndicate{/link} pays its rabble in gold for every {link:stromgarde-keep}Stromgarde{/link} badge cut from a dead militiaman. Nials would not let the brigands profit from her dead. When the badges came back, she did not hang them as trophies. She sent word to each family that their soldier had died in battle, for she held that grim news was kinder than silence.]=],
		},
	},
	mentions = {
		{
			text = [=[Plea To The {link:alliance}Alliance{/link}, the dwarves' request]=],
			unlock = {
				{ type = "quest", id = 634 },
			},
		},
		{
			text = "{link:northfold-manor}Northfold Manor{/link}",
			unlock = {
