	sections = {
		{
			title = "Summary",
			text = [=[Drum Fel leads the warriors of {link:hammerfall}Hammerfall{/link}. He has no time to sharpen his own axe, for trolls and ogres strike at his walls day after day. He has little patience for the untried, but he will take any fighter who proves strong enough, and there is no end of fighting to give them.]=],
		},
