			title = "Significance",
			text = [=[Drum Fel is the will that holds {link:hammerfall}Hammerfall{/link}. He means to show the peoples of the highlands that the orcs, too, have a home here, and that they will not be driven from it.]=],
		},
		{
			title = "Deeds",
			text = [=[• He sends his fighters against the {link:witherbark-trolls}Witherbark trolls{/link} in the south, who turned their backs on the orcs.
• He sends them against the {link:boulderfist-ogres}Boulderfist{/link} maulers and magi of {link:boulderfist-hall}Boulderfist Hall{/link}.
• He strikes at the Boulderfist lords and shaman in the ruins of {link:stromgarde-keep}Stromgarde{/link}.
• Years ago, he defeated the {link:ogres}ogre{/link} {link:or-kalar}Or'Kalar{/link}.]=],
		},
		{
			title = "Unrecorded",
			text = [=[The records of {link:hammerfall}Hammerfall{/link} do not say where Drum Fel fought before he came here, or when he first met {link:or-kalar}Or'Kalar{/link}.]=],
		},
