			title = "Summary",
			text = [=[Myzrael is a being of the deep earth who lies bound beneath the {link:arathi-highlands}Arathi Highlands{/link}. She calls herself a princess of the earth. The giants chained her there, and four Stones of Binding hold her pinned. Only through crystal shards can she speak to the world above, and she speaks sweetly, begging for rescue.]=],
		},
		{
			title = "Significance",
			text = [=[Myzrael is the secret of the highlands. The {link:twilight-s-hammer}Twilight's Hammer{/link} calls her the Lady and works for her return. The one who fled their order with her scroll believes that the giants bound her for a reason, and that she must never be allowed to grow strong.]=],
		},
		{
			title = "Deeds",
			text = [=[• She calls to travellers in visions through a shard of her crystal.
• She sends them to wake the shards held by the {link:drywhisker-kobolds}Drywhisker kobolds{/link}.
• She asks for the three keys of the Stones of Binding, and for the Rod of Order from the stone watcher {link:fozruk}Fozruk{/link}.
• She names allies of hers in {link:ironforge}Ironforge{/link} and in {link:hammerfall}Hammerfall{/link}.]=],
		},
		{
			title = "Unrecorded",
			text = [=[No chronicle of {link:azeroth}Azeroth{/link} speaks of Myzrael. What she is, where she came from and why the giants bound her are known only from her own words and from those of {link:theldurin-the-lost}Theldurin the Lost{/link}.]=],
		},
	},
	chapters = {
