Add({
	kind = "figure",
	id = "thoradin",
	title = "Thoradin",
	subtitle = "First King of Arathor",
	tier = "A",
	region = "arathi-highlands",
	allegiance = "The Arathi tribe · Arathor",
	unlock = {
		{ type = "read" },
		{ type = "quest", id = 641 },
	},
	sections = {
		{
			title = "Summary",
			text = [=[Thoradin was the warlord of the {link:arathi-highlands}Arathi{/link} tribe who made humankind a nation. In an age when the human tribes of the north fought one another while the trolls hunted them all, he bound them under one banner. He named the new realm {link:arathor}Arathor{/link} and raised its capital, {link:stromgarde-keep}Strom{/link}, in the highlands that bear his tribe's name. Every human kingdom of the present day descends from his work.]=],
		},
		{
			title = "Significance",
			text = [=[Before Thoradin there were tribes. After him there was a people. His alliance with the elves won the {link:troll-wars}Troll Wars{/link} and brought the knowledge of magic to humankind, and his bloodline was honored by the elves of {link:quel-thalas}Quel'Thalas{/link} for thousands of years. The great wall between the highlands and {link:hillsbrad-foothills}Hillsbrad{/link} still bears his name.]=],
		},
		{
			title = "The Uniting of the Tribes",
			text = [=[The {link:arathi-highlands}Arathi{/link} had fought the Amani longer than any other tribe, and Thoradin had learned war on the troll frontier. He saw what the other chieftains would not: that the trolls would destroy the tribes one by one. He brought them together by every means he had. Some he won by marriage, some by promises of land and wealth, and some he defeated in battle. Those he defeated he did not humble. He made their chiefs his generals, and so they became his most loyal men.]=],
		},
		{
			title = "Strom",
			text = [=[Thoradin set his capital on the dry plains of the highlands, far from the dense forests where the trolls laid their ambushes. The fortress of {link:stromgarde-keep}Strom{/link} became a place of refuge, and humans came to it from across the continent. Here, too, humankind first learned the arcane arts.]=],
		},
		{
			title = "The Troll Wars",
			text = [=[When the Amani fell upon {link:quel-thalas}Quel'Thalas{/link}, the elves sent envoys to {link:stromgarde-keep}Strom{/link}. They promised to teach a hundred humans the ways of magic in return for the swords of {link:arathor}Arathor{/link}. Thoradin accepted. His host struck the trolls in the south of the elven lands and drew them into the foothills of the {link:alterac-mountains}Alterac Mountains{/link}, where the elves and the new human magi fell upon them from the other side. The Amani were broken. In gratitude, the elves swore an oath of friendship to Thoradin's line.]=],
		},
		{
			title = "The Legacy",
			text = [=[Thoradin wished {link:stromgarde-keep}Strom{/link} to remain the heart of his realm, and he feared an empire spread too wide. After him, his people went out anyway and founded {link:dalaran}Dalaran{/link}, {link:gilneas}Gilneas{/link}, {link:kul-tiras}Kul Tiras{/link}, {link:alterac-mountains}Alterac{/link} and Lordaeron. Strom declined. At last the last of his bloodline left it and sailed south to found a new kingdom. Many centuries later, {link:anduin-lothar}Anduin Lothar{/link}, the last of that line, led the {link:alliance}Alliance{/link} of {link:lordaeron}Lordaeron{/link} in the {link:second-war}Second War{/link}.]=],
		},
		{
			title = "Unrecorded",
			text = [=[The histories say little of Thoradin's own family, of his last years or of his death. This entry does not guess at them.]=],
		},
	},
	chapters = {
		{
			key = "the-sigil-of-thoradin",
			title = "The Sigil of Thoradin",
			hint = "Follow the broken sigil that bears the first king's name.",
			unlock = {
				{ type = "quest", id = 641 },
			},
			text = [=[Among the seals that guard the tomb of the Trollbanes is a sigil named for Thoradin. Prince {link:prince-galen-trollbane}Galen{/link} broke it and scattered its pieces among his last defenders. The pieces were taken from their bodies, and a troll shaman of the {link:horde}Horde{/link} bound them whole again. The first king's name had become a key in the hands of the trolls his people once defeated.]=],
		},
	},
	mentions = {
		{
			text = "The Broken Sigil",
			unlock = {
				{ type = "quest", id = 640 },
			},
		},
		{
			text = "Sigil of Thoradin",
			unlock = {
				{ type = "quest", id = 641 },
			},
		},
	},
	bonds = {
		{ id = "arathor", name = "Arathor", note = "the nation he founded" },
		{ id = "anduin-lothar", name = "Anduin Lothar", note = "the last of his line" },
		{ id = "thoradin-s-wall", name = "Thoradin's Wall", note = "bears his name" },
		{ id = "stromgarde-keep", name = "Stromgarde Keep", note = "once his capital, Strom" },
	},
})

