		},
	},
	bonds = {
		{ id = "prince-galen-trollbane", name = "Prince Galen Trollbane", note = "his son" },
		{ id = "terenas-menethil", name = "Terenas Menethil", note = "his ally in the Alliance" },
		{ id = "trol-kalar", name = "Trol'kalar", note = "the sword of his house" },
