Add({
	kind = "topic",
	id = "trol-kalar",
	title = "Trol'kalar",
	category = "artifact",
	region = "arathi-highlands",
	unlock = {
		{ type = "read" },
		{ type = "quest", id = 638 },
	},
	sections = {
		{
			title = "Summary",
			text = [=[Trol'kalar is the ancient sword of the house of Trollbane. Its name means troll slayer in the tongue of the trolls themselves. It was borne in the wars of {link:arathor}Arathor{/link} by Lord Ignaeus of {link:stromgarde-keep}Strom{/link}, the most feared enemy the trolls ever faced, and it gave his house its name.]=],
		},
		{
			title = "The Tomb",
			text = [=[When {link:thoras-trollbane}King Thoras{/link} died, Trol'kalar was laid in his tomb in the Sanctum behind the chapel of {link:stromgarde-keep}Stromgarde{/link}, held in the grip of stone hands. The tomb was sealed with wardings that answer only to a sigil. Prince {link:prince-galen-trollbane}Galen{/link} divided that sigil into four: the Sigil of Strom, the Sigil of {link:thoradin}Thoradin{/link}, the Sigil of {link:arathor}Arathor{/link} and the Sigil of Trollbane. One fell to the {link:syndicate}Syndicate{/link} with the city. The others he gave to his soldiers, his cavalry leader and himself. Brought together, the four become one, the Sigil of Ignaeus.]=],
		},
		{
			title = "In the Present Day",
			text = [=[{link:vol-jin}Vol'jin{/link} of the {link:darkspear-trolls}Darkspear{/link} wants the sword. He has sent the hunter {link:zengu}Zengu{/link} to {link:hammerfall}Hammerfall{/link} to take it, so that the troll slayer of {link:stromgarde-keep}Strom{/link} may be turned against the Gurubashi trolls of {link:zul-gurub}Zul'Gurub{/link}.]=],
		},
	},
})

Add({
	kind = "topic",
	id = "witherbark-trolls",
	title = "Witherbark Trolls",
	aliases = { "Witherbark", "Witherbark trolls", "Witherbark tribe" },
	category = "group",
	region = "arathi-highlands",
	unlock = {
		{ type = "read" },
		{ type = "target" },
	},
	sections = {
		{
			title = "Summary",
			text = [=[The Witherbark are a tribe of forest {link:trolls}trolls{/link} who live in the south-east of the {link:arathi-highlands}Arathi Highlands{/link}. Their village stands among the hills there, with caverns behind it where their warband leaders gather. Trolls have fought the humans of {link:stromgarde-keep}Strom{/link} since the days of {link:thoradin}Thoradin{/link}, and the Witherbark still hold that war close to their hearts.]=],
		},
		{
			title = "Their Ways",
			text = [=[The tribe has axe throwers, headhunters, berserkers and witch doctors who carry pouches of medicine and bloodstone amulets. Its shadow hunters are given a special knife when they complete the rites of their passage. Two warband leaders, Zalas Witherbark and Nimar the Slayer, lead them to war.]=],
		},
		{
			title = "In the Present Day",
			text = [=[The Witherbark once fought beside the orcs, and then they left them. Now they have joined the {link:boulderfist-ogres}Boulderfist ogres{/link} to drive the {link:horde}Horde{/link} out of {link:hammerfall}Hammerfall{/link}. Their fighters share the {link:ogres}ogre{/link} mound of {link:boulder-gor}Boulder'gor{/link}, and berserkers of the tribe stand beside the ogres in the ruins of {link:stromgarde-keep}Stromgarde{/link}. {link:drum-fel}Drum Fel{/link} of Hammerfall has made them the first target of his war.]=],
		},
	},
})

Add({
