	unlock = {
		{ type = "read" },
		{ type = "target" },
	},
	sections = {
		{
			title = "Summary",
			text = [=[The Boulderfist are the greatest clan of {link:ogres}ogres{/link} in the {link:arathi-highlands}Arathi Highlands{/link}. They hold the mound of {link:boulder-gor}Boulder'gor{/link}, the caves of {link:boulderfist-hall}Boulderfist Hall{/link} and a great part of the ruined city of {link:stromgarde-keep}Stromgarde{/link}. No chronicle records when they came to the highlands.]=],
		},
		{
			title = "Their Ways",
			text = [=[They are brutes, enforcers, maulers and lords, with magi and shaman who have learned to use the treasures they plunder. Their shaman prize the azure agates taken from the Tower of {link:arathor}Arathor{/link}. In {link:boulderfist-hall}Boulderfist Hall{/link}, the {link:ogres}ogre{/link} mage {link:kor-gresh-coldrage}Kor'gresh Coldrage{/link} throws ice from a stolen wand. In {link:stromgarde-keep}Stromgarde{/link}, the ogre {link:or-kalar}Or'Kalar{/link} commands them in the name of {link:mug-thol}Mug'thol{/link}, a warlord who is not of the highlands.]=],
		},
		{
			title = "In the Present Day",
			text = [=[The Boulderfist fight the soldiers of {link:stromgarde-keep}Stromgarde{/link} and the {link:syndicate}Syndicate{/link} for the ruins of the city, and they have joined the {link:witherbark-trolls}Witherbark trolls{/link} against {link:hammerfall}Hammerfall{/link}. Kovork, Molok the Crusher, {link:ruul-eagletalon}Ruul{/link} Onestone and Foulbelly are feared among their chiefs.]=],
		},
	},
})

