Add({
	kind = "topic",
	id = "league-of-arathor",
	title = "League of Arathor",
	category = "group",
	region = "arathi-highlands",
	unlock = {
		{ type = "read" },
		{ type = "interact" },
	},
	sections = {
		{
			title = "Summary",
			text = [=[The League of Arathor is the fighting force of what remains of the kingdom of {link:stromgarde-keep}Stromgarde{/link}. Its soldiers are the heirs of a proud realm whose capital is now held by ogres and brigands. They have sworn to win back the highlands for the people of Stromgarde and for the {link:alliance}Alliance{/link}.]=],
		},
		{
			title = "Their Cause",
			text = [=[The League makes its camp at {link:refuge-pointe}Refuge Pointe{/link} under {link:field-marshal-oslight}Field Marshal Oslight{/link}. Its first battle is for {link:arathi-basin}Arathi Basin{/link}, a fertile valley of farms, mines, forges and forests. The League means to claim the basin's riches for its allies in {link:stormwind-city}Stormwind{/link}, and through Stormwind for the whole {link:alliance}Alliance{/link}. Its soldiers hold Trollbane Hall, at the edge of the valley, named for the royal house of {link:stromgarde-keep}Stromgarde{/link}.]=],
		},
		{
			title = "In the Present Day",
			text = [=[The League faces the {link:defilers}Forsaken Defilers{/link} in the basin. Its supply officer, Samuel Hawke, sends provisions to those who fight, and its sergeants urge every soldier to strike before the enemy can.]=],
		},
	},
})

Add({
