	sections = {
		{
			title = "Summary",
			text = [=[The Defilers are elite troops of the {link:forsaken}Forsaken{/link}, sent to the {link:arathi-highlands}Arathi Highlands{/link} under the watchful eye of {link:varimathras}Varimathras{/link}. They fight the {link:league-of-arathor}League of Arathor{/link} for {link:arathi-basin}Arathi Basin{/link}. Their purpose is not the orcs' war but their own queen's: to cut the humans of the north off from their dwarven allies in the south, and to seize the basin's riches for the {link:undercity}Undercity{/link}.]=],
		},
